-- All fixtures and temporary gateway configuration roll back in this transaction.
begin;
do $$
declare key_value text:=repeat('a',64);owner_id uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();legacy_id uuid:=gen_random_uuid();email_value text:='veyra-qa-'||owner_id::text||'@example.invalid';other_email text:='veyra-qa-'||other_id::text||'@example.invalid';password_value text:='Test-password-only-42';next_password text:='Next-password-only-84';token_value text:=encode(extensions.gen_random_bytes(32),'hex');other_token text:=encode(extensions.gen_random_bytes(32),'hex');before_hash text;result jsonb;factor_secret bytea;code text;current_step bigint:=floor(extract(epoch from clock_timestamp())/30);codes jsonb;fresh_codes jsonb;widget_id uuid;attempt int;rejected boolean:=false;
begin
 assert veyra_private.base32(convert_to('12345678901234567890','utf8'))='GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ','Base32 vector';
 assert veyra_private.totp(convert_to('12345678901234567890','utf8'),1)='287082','RFC6238 SHA1 vector 59';
 assert veyra_private.totp(convert_to('12345678901234567890','utf8'),37037036)='081804','RFC6238 SHA1 vector 1111111109';
 assert veyra_private.totp(convert_to('12345678901234567890','utf8'),666666666)='353130','RFC6238 SHA1 vector 20000000000';
 update veyra_private.config set gateway_hash=encode(extensions.digest(key_value,'sha256'),'hex');
 before_hash:=extensions.crypt(password_value,extensions.gen_salt('bf',12));
 insert into veyra_private.accounts(id,email,password_hash,verified) values(owner_id,email_value,before_hash,true),(other_id,other_email,before_hash,true);
 insert into veyra_private.sessions(token_hash,user_id,expires_at) values(encode(extensions.digest(token_value,'sha256'),'hex'),owner_id,now()+interval '1 day'),(encode(extensions.digest(other_token,'sha256'),'hex'),owner_id,now()+interval '1 day');
 result:=veyra_private.security_api(key_value,'mfa-begin',jsonb_build_object('token',token_value,'currentPassword','wrong'),'qa');assert result->>'status'='403','Wrong enrollment password';
 result:=veyra_private.security_api(key_value,'mfa-begin',jsonb_build_object('token',token_value,'currentPassword',password_value),'qa');assert result->>'status'='200' and length(result->>'secret')=32,'Pending enrollment';
 result:=veyra_private.security_api(key_value,'mfa-status',jsonb_build_object('token',token_value),'qa');assert result->>'enabled'='false','Enrollment not enabled yet';
 select extensions.pgp_sym_decrypt_bytea(pending,key_value||':totp:v1') into factor_secret from veyra_private.mfa where user_id=owner_id;
 result:=veyra_private.security_api(key_value,'mfa-confirm',jsonb_build_object('token',token_value,'currentPassword',password_value,'mfa_code','bad'),'qa');assert result->>'status'='400','Reject malformed enrollment code';
 code:=veyra_private.totp(factor_secret,current_step);
 result:=veyra_private.security_api(key_value,'mfa-confirm',jsonb_build_object('token',token_value,'currentPassword',password_value,'mfa_code',code),'qa');assert result->>'status'='200','Confirm enrollment';codes:=result->'recovery_codes';assert jsonb_array_length(codes)=10,'Ten recovery codes';
 assert not exists(select 1 from veyra_private.sessions where token_hash=encode(extensions.digest(other_token,'sha256'),'hex')),'Revoke previous sessions';
 result:=veyra_private.account_api(key_value,'login',jsonb_build_object('email',email_value,'password',password_value),'qa');assert result->>'mfa_required'='true' and not result?'access_token','No session before MFA';
 result:=veyra_private.account_api(key_value,'login',jsonb_build_object('email',email_value,'password',password_value,'mfa_code',code),'qa');assert result->>'status'='400','Enrollment TOTP replay blocked';
 code:=veyra_private.totp(factor_secret,current_step+1);
 result:=veyra_private.account_api(key_value,'login',jsonb_build_object('email',email_value,'password',password_value,'mfa_code',code),'qa');assert result?'access_token','Valid next TOTP accepted';
 result:=veyra_private.account_api(key_value,'login',jsonb_build_object('email',email_value,'password',password_value,'mfa_code',code),'qa');assert result->>'status'='400','Login TOTP replay blocked';
 result:=veyra_private.account_api(key_value,'login',jsonb_build_object('email',email_value,'password',password_value,'mfa_code',codes->>0),'qa');assert result?'access_token','Recovery login';
 result:=veyra_private.account_api(key_value,'login',jsonb_build_object('email',email_value,'password',password_value,'mfa_code',codes->>0),'qa');assert result->>'status'='400','Recovery code single use';
 insert into veyra_private.codes(email,purpose,code_hash,expires_at) values(email_value,'reset',encode(extensions.hmac(email_value||':reset:12345678',key_value,'sha256'),'hex'),now()+interval '10 minutes');
 result:=veyra_private.account_api(key_value,'reset',jsonb_build_object('email',email_value,'code','12345678','password',next_password),'qa');assert result->>'mfa_required'='true','Email reset cannot bypass MFA';
 assert (select password_hash=before_hash from veyra_private.accounts where id=owner_id),'Password unchanged before MFA';
 result:=veyra_private.account_api(key_value,'reset',jsonb_build_object('email',email_value,'code','12345678','password',next_password,'mfa_code',codes->>1),'qa');assert result?'access_token','Reset with recovery factor';token_value:=result->>'access_token';
 assert (select enabled_at is not null from veyra_private.mfa where user_id=owner_id),'Reset retains MFA';
 result:=veyra_private.security_api(key_value,'mfa-recovery',jsonb_build_object('token',token_value,'currentPassword',next_password,'mfa_code',codes->>2),'qa');assert result->>'status'='200','Recovery rotation';fresh_codes:=result->'recovery_codes';
 result:=veyra_private.account_api(key_value,'login',jsonb_build_object('email',email_value,'password',next_password,'mfa_code',codes->>3),'qa');assert result->>'status'='400','Rotated old codes invalid';
 result:=veyra_private.browser_api(key_value,'profile-save',jsonb_build_object('token',token_value,'display_name','User <script>','device_name','Test PC','platform','windows','avatar','data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a9uEAAAAASUVORK5CYII='),'qa');assert result->>'status'='200' and result->>'display_name'='User <script>','Profile raster avatar and literal text';
 result:=veyra_private.browser_api(key_value,'profile-save',jsonb_build_object('token',token_value,'avatar','data:image/svg+xml,<svg/>'),'qa');assert result->>'status'='400','SVG avatar rejected';
 result:=veyra_private.browser_api(key_value,'widget-publish',jsonb_build_object('token',token_value,'title','Test widget','template',jsonb_build_object('kind','custom','style','plain','package',jsonb_build_object('format','veyra-widget','version',1,'permissions','[]'::jsonb,'design',jsonb_build_object('elements','[]'::jsonb),'js','document.body.textContent="test"'))),'qa');assert result->>'status'='200','Custom widget publication';widget_id:=(result->>'id')::uuid;
 result:=veyra_private.browser_api(key_value,'widget-list','{}','qa');assert result->>'status'='200' and not exists(select 1 from jsonb_array_elements(result->'widgets') w where w->'template'?'package'),'Catalogue excludes full code';
 result:=veyra_private.browser_api(key_value,'widget-get',jsonb_build_object('id',widget_id),'qa');assert result->'widget'->'template'->'package'->>'format'='veyra-widget','Public package retrieval';
 insert into veyra_private.sessions(token_hash,user_id,expires_at) values(encode(extensions.digest(other_token,'sha256'),'hex'),other_id,now()+interval '1 day');
 result:=veyra_private.browser_api(key_value,'widget-delete',jsonb_build_object('token',other_token,'id',widget_id),'qa');assert exists(select 1 from veyra_private.widgets where id=widget_id),'Cross-owner deletion blocked';
 result:=veyra_private.security_api(key_value,'mfa-disable',jsonb_build_object('token',token_value,'currentPassword',next_password,'mfa_code',fresh_codes->>0),'qa');assert result->>'status'='429','Per-account MFA rate bound';
 update veyra_private.rate_limits set started_at=now()-interval '11 minutes' where key='mfa:'||owner_id::text;
 result:=veyra_private.security_api(key_value,'mfa-disable',jsonb_build_object('token',token_value,'currentPassword',next_password,'mfa_code',fresh_codes->>0),'qa');assert result->>'status'='200','Disable with password and fresh recovery code';
 assert not exists(select 1 from veyra_private.mfa where user_id=owner_id),'Factor removed';
 -- Registration replacement cannot activate an attacker password by email alone.
 update veyra_private.accounts set verified=false where id=other_id;
 insert into veyra_private.codes(email,purpose,code_hash,expires_at) values(other_email,'verify',encode(extensions.hmac(other_email||':verify:87654321',key_value,'sha256'),'hex'),now()+interval '10 minutes');
 result:=veyra_private.account_api(key_value,'verify',jsonb_build_object('email',other_email,'code','87654321','password','Wrong-owner-password'),'qa');assert result->>'status'='400','Verification must prove chosen registration password';
 assert (select not verified from veyra_private.accounts where id=other_id),'No activation with mismatched credentials';
 result:=veyra_private.account_api(key_value,'verify',jsonb_build_object('email',other_email,'code','87654321','password',password_value),'qa');assert result?'access_token','Matching password and email code verified';
 insert into auth.users(id,email) values(legacy_id,'veyra-legacy-qa-'||legacy_id::text||'@example.invalid');
 for attempt in 1..10 loop insert into public.veyra_sync(user_id,device_id,platform,payload) values(legacy_id,gen_random_uuid(),'windows','{}');end loop;
 begin insert into public.veyra_sync(user_id,device_id,platform,payload) values(legacy_id,gen_random_uuid(),'windows','{}');exception when raise_exception then rejected:=true;end;
 assert rejected,'Legacy eleventh backup denied';
 assert not has_table_privilege('anon','veyra_private.mfa','SELECT'),'No anon MFA table read';
 assert not has_function_privilege('anon','veyra_private.mfa_check(text,uuid,text,boolean)','EXECUTE'),'No anon MFA helper call';
end $$;
rollback;
select 'PASS: RFC vectors, enrollment proof, session revocation, MFA login/reset, replay and recovery rotation, avatar validation, package publication/ownership, registration binding, legacy quota, grants. Fixtures rolled back.' as result;
